"""A byte-oriented, permissive CSV reader with precise input positions."""


class CSVError(Exception):
    pass


class CSVReader:
    def __init__(self, data, delimiter=44):
        self.data = data
        self.delimiter = delimiter
        self.offset = 0
        self.line = 1
        self.record = 0
        self.fields = None
        self.first = True

    def __iter__(self):
        return self

    def __next__(self):
        data = self.data
        n = len(data)
        start = self.offset
        line_start = self.line
        pos = start
        if self.first:
            self.first = False
            if data.startswith(b'\xef\xbb\xbf'):
                pos = 3
        # Empty physical records do not count, but remain part of the next
        # record's reported position.
        while pos < n and data[pos] in (10, 13):
            if data[pos] == 10:
                self.line += 1
            pos += 1
        if pos == n:
            self.offset = pos
            raise StopIteration
        values = []
        value = bytearray()
        # Field-start, unquoted, quoted, and after-closing-quote states.
        state = 0
        delimiter = self.delimiter
        while pos < n:
            c = data[pos]
            pos += 1
            if c == 10:
                self.line += 1
            if state == 2:
                if c == 34:
                    state = 3
                else:
                    value.append(c)
                continue
            if state == 3:
                if c == 34:
                    value.append(34)
                    state = 2
                    continue
                state = 1
            elif state == 0 and c == 34:
                state = 2
                continue
            if c == delimiter:
                values.append(bytes(value))
                value.clear()
                state = 0
            elif c in (10, 13):
                break
            else:
                value.append(c)
                state = 1
        values.append(bytes(value))
        self.offset = pos
        index = self.record
        self.record += 1
        count = len(values)
        if self.fields is None:
            self.fields = count
        elif count != self.fields:
            raise CSVError(
                f'CSV error: record {index} (line: {line_start}, byte: {start}): '
                f'found record with {count} fields, but the previous record has '
                f'{self.fields} fields')
        result = []
        for field, value in enumerate(values):
            try:
                result.append(value.decode('utf-8'))
            except UnicodeDecodeError as e:
                raise CSVError(
                    f'CSV parse error: record {index} (line {line_start}, '
                    f'field: {field}, byte: {start}): invalid utf-8: invalid UTF-8 '
                    f'in field {field} near byte index {e.start}') from None
        return result
