"""Command line interface and user-facing argument diagnostics."""
import os
import re
import sys
from dataclasses import dataclass

STYLES = ('none', 'ascii', 'ascii2', 'sharp', 'rounded', 'reinforced', 'markdown', 'grid')
ALIGNS = ('left', 'center', 'right')
OPTIONS = {
    'no-headers': None,
    'number': None,
    'tsv': None,
    'delimiter': 'DELIMITER',
    'style': 'STYLE',
    'padding': 'PADDING',
    'indent': 'INDENT',
    'sniff': 'LIMIT',
    'header-align': 'HEADER_ALIGN',
    'body-align': 'BODY_ALIGN',
    'disable-pager': None,
    'help': None,
    'version': None,
}
SHORT = dict(zip('HntdspiPhV', ('no-headers', 'number', 'tsv', 'delimiter', 'style',
                               'padding', 'indent', 'disable-pager', 'help', 'version')))
FOOTER = "For more information, try '--help'.\n"

HELP = '''A high performance csv viewer with cjk/emoji support.

Usage: {prog} [OPTIONS] [FILE]

Arguments:
  [FILE]
          File to view

Options:
  -H, --no-headers
          Specify that the input has no header row
  -n, --number
          Prepend a column of line numbers to the table
  -t, --tsv
          Use '\\t' as delimiter for tsv
  -d, --delimiter <DELIMITER>
          Specify the field delimiter [default: ,]
  -s, --style <STYLE>
          Specify the border style [default: sharp] [possible values: none, ascii, ascii2, sharp,
          rounded, reinforced, markdown, grid]
  -p, --padding <PADDING>
          Specify padding for table cell [default: 1]
  -i, --indent <INDENT>
          Specify global indent for table [default: 0]
      --sniff <LIMIT>
          Limit column widths sniffing to the specified number of rows. Specify "0" to cancel limit
          [default: 1000]
      --header-align <HEADER_ALIGN>
          Specify the alignment of the table header [default: center] [possible values: left,
          center, right]
      --body-align <BODY_ALIGN>
          Specify the alignment of the table body [default: left] [possible values: left, center,
          right]
  -P, --disable-pager
          Disable pager
  -h, --help
          Print help
  -V, --version
          Print version
'''


@dataclass
class Config:
    file: str = None
    no_headers: bool = False
    number: bool = False
    tsv: bool = False
    delimiter: int = 44
    style: str = 'sharp'
    padding: int = 1
    indent: int = 0
    sniff: int = 1000
    header_align: str = 'center'
    body_align: str = 'left'
    disable_pager: bool = False


class CLIExit(Exception):
    def __init__(self, text, status=2):
        self.text = text
        self.status = status


def label(name):
    arg = OPTIONS[name]
    return '--' + name + (' <' + arg + '>' if arg else '')


def choices(name):
    return STYLES if name == 'style' else ALIGNS if name.endswith('-align') else ()


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    distance = max(0, max(len(a), len(b)) // 2 - 1)
    aa, bb = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i - distance), min(len(b), i + distance + 1)):
            if not bb[j] and c == b[j]:
                aa[i] = bb[j] = True
                break
    matched = sum(aa)
    if not matched:
        return 0.0
    left = [c for i, c in enumerate(a) if aa[i]]
    right = [c for j, c in enumerate(b) if bb[j]]
    transpositions = sum(x != y for x, y in zip(left, right)) / 2
    score = (matched / len(a) + matched / len(b) + (matched - transpositions) / matched) / 3
    if score > 0.7:
        prefix = 0
        for x, y in zip(a[:4], b[:4]):
            if x != y:
                break
            prefix += 1
        score += prefix * 0.1 * (1 - score)
    return score


def suggestion(text, candidates):
    best, best_score = None, 0.8
    for candidate in candidates:
        score = jaro_winkler(text, candidate)
        if score > best_score:
            best, best_score = candidate, score
    return best


class Parser:
    def __init__(self, prog):
        self.prog = prog
        self.config = Config()
        self.seen = []

    def usage(self, body='[OPTIONS] [FILE]'):
        return f'Usage: {self.prog} {body}\n'

    def group_usage(self):
        names = ['FILE'] + [label(n) for n in OPTIONS if n not in ('help', 'version')]
        return self.usage('<' + '|'.join(names) + '>')

    def fail(self, text, usage=None):
        raise CLIExit('error: ' + text + '\n\n' + (usage + '\n' if usage else '') + FOOTER)

    def unexpected(self, arg, positional=False):
        tip = None
        if arg.startswith('--'):
            tip = suggestion(arg[2:].split('=')[0], OPTIONS)
        text = f"unexpected argument '{arg}' found"
        usage = self.usage()
        if tip:
            text += f"\n\n  tip: a similar argument exists: '--{tip}'"
            usage = self.group_usage()
        elif not positional:
            text += f"\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'"
        self.fail(text, usage)

    def missing(self, name):
        text = f"a value is required for '{label(name) if name != 'FILE' else '[FILE]'}' but none was supplied"
        opts = choices(name)
        if opts:
            text += '\n  [possible values: ' + ', '.join(opts) + ']'
        self.fail(text)

    def convert(self, name, value):
        opts = choices(name)
        if opts:
            if not value:
                self.missing(name)
            if value.lower() in opts:
                return value.lower()
            text = f"invalid value '{value}' for '{label(name)}'"
            text += '\n  [possible values: ' + ', '.join(opts) + ']'
            tip = suggestion(value, opts)
            if tip:
                text += f"\n\n  tip: a similar value exists: '{tip}'"
            self.fail(text)
        elif name == 'delimiter':
            if len(value) == 1:
                return ord(value) & 255
            reason = 'cannot parse char from empty string' if not value else 'too many characters in string'
        else:
            if not value:
                reason = 'cannot parse integer from empty string'
            elif not re.fullmatch(r'\+?[0-9]+', value):
                reason = 'invalid digit found in string'
            elif int(value) > 18446744073709551615:
                reason = 'number too large to fit in target type'
            else:
                return int(value)
        self.fail(f"invalid value '{value}' for '{label(name)}': {reason}")

    def known_option(self, token):
        if token == '--':
            return True
        if token.startswith('--'):
            return token[2:].split('=')[0] in OPTIONS
        return len(token) > 1 and token[0] == '-' and token[1] in SHORT

    def set_option(self, name, value=None, explicit=False):
        if name in self.seen:
            self.fail(f"the argument '{label(name)}' cannot be used multiple times", self.usage())
        if OPTIONS[name] is None:
            if explicit:
                usage = self.usage(label(name) + ' [FILE]') if not self.seen else self.group_usage()
                self.fail(f"unexpected value '{value}' for '--{name}' found; no more were expected", usage)
            if name == 'help':
                raise CLIExit(HELP.format(prog=self.prog), 0)
            if name == 'version':
                raise CLIExit('csview 1.3.4\n', 0)
            value = True
        else:
            value = self.convert(name, value)
        self.seen.append(name)
        setattr(self.config, name.replace('-', '_'), value)

    def parse(self, argv):
        i = 0
        positional = False
        while i < len(argv):
            token = argv[i]
            i += 1
            if not positional and token == '--':
                positional = True
                continue
            if positional or token == '-' or not token.startswith('-'):
                if self.config.file is not None:
                    self.unexpected(token, True)
                if not token:
                    self.missing('FILE')
                self.config.file = token
                continue
            if token.startswith('--'):
                part = token[2:].split('=', 1)
                name = part[0]
                if name not in OPTIONS:
                    self.unexpected('--' + name)
                attached = len(part) == 2
                if OPTIONS[name] is None:
                    self.set_option(name, part[1] if attached else None, attached)
                    continue
                if attached:
                    value = part[1]
                else:
                    if i == len(argv):
                        self.missing(name)
                    value = argv[i]
                    if value.startswith('-') and value != '-':
                        if self.known_option(value):
                            self.missing(name)
                        self.unexpected(value if value.startswith('--') else value[:2])
                    i += 1
                self.set_option(name, value, True)
                continue
            j = 1
            while j < len(token):
                short = token[j]
                if short not in SHORT:
                    self.unexpected('-' + short)
                name = SHORT[short]
                j += 1
                if OPTIONS[name] is None:
                    self.set_option(name)
                    continue
                if j < len(token):
                    value = token[j:]
                    if value.startswith('='):
                        value = value[1:]
                else:
                    if i == len(argv):
                        self.missing(name)
                    value = argv[i]
                    if value.startswith('-') and value != '-':
                        if self.known_option(value):
                            self.missing(name)
                        self.unexpected(value if value.startswith('--') else value[:2])
                    i += 1
                self.set_option(name, value, True)
                break
        if 'tsv' in self.seen and 'delimiter' in self.seen:
            first, second = sorted(('tsv', 'delimiter'), key=self.seen.index)
            used = [label(n) for n in self.seen if n != second]
            used.append('<FILE>' if self.config.file is not None else '[FILE]')
            self.fail(f"the argument '{label(first)}' cannot be used with '{label(second)}'",
                      self.usage(' '.join(used)))
        if self.config.tsv:
            self.config.delimiter = 9
        return self.config


def parse_args(argv=None):
    return Parser(os.path.basename(sys.argv[0]) or 'executable').parse(
        sys.argv[1:] if argv is None else argv)
PY"}

