"""Unicode-aware measuring, grapheme-safe clipping, and cell alignment."""
from bisect import bisect_right
from functools import lru_cache
import unicodedata

from width_data import ZERO, WIDE, THREE, MEASURE_WIDE, MEASURE_THREE
from sequence_data import VS16, VS15_NARROW, MODIFIER_BASE, EMOJI_DEFAULT, PICTOGRAPHIC


def contains(table, cp):
    at = bisect_right(table, (cp, 0x110000)) - 1
    return at >= 0 and cp <= table[at][1]


@lru_cache(maxsize=32768)
def char_width(cp, measuring=False):
    if cp < 0xAD:
        # The handful of low ambiguous symbols are still handled below.
        if cp not in (0xA1, 0xA4, 0xA7, 0xA8, 0xAA):
            return 1
    if contains(ZERO, cp):
        return 0
    if contains(MEASURE_THREE if measuring else THREE, cp):
        return 3
    if contains(MEASURE_WIDE if measuring else WIDE, cp):
        return 2
    return 1


LAM = {0x644, 0x6B5, 0x6B6, 0x6B7, 0x6B8, 0x76A, 0x8A6, 0x8C7}
ALEF = {0x622, 0x623, 0x625, 0x627, 0x671, 0x672, 0x673, 0x675, 0x773, 0x774,
        *range(0x870, 0x883)}


@lru_cache(maxsize=32768)
def text_width(text, measuring=False):
    if text.isascii():
        return len(text) - text.count('\r\n')
    cps = [ord(c) for c in text]
    total = 0
    i = 0
    last_emoji = False
    joined = False
    while i < len(cps):
        cp = cps[i]
        if cp == 0x200D:
            joined = last_emoji
            last_emoji = False
            i += 1
            continue
        w = char_width(cp, measuring)
        emoji = contains(EMOJI_DEFAULT, cp)
        can_join = emoji
        can_continue = emoji
        end = i + 1
        if cp == 13 and end < len(cps) and cps[end] == 10:
            end += 1
        elif end < len(cps) and cps[end] == 0xFE0F:
            if contains(VS16, cp) or emoji:
                w = 2
                can_join = can_continue = True
            end += 1
        elif end < len(cps) and cps[end] == 0xFE0E:
            if not measuring and contains(VS15_NARROW, cp):
                w = 1
            can_join = emoji and measuring
            can_continue = False
            end += 1
        elif end < len(cps) and 0x1F3FB <= cps[end] <= 0x1F3FF and contains(MODIFIER_BASE, cp):
            w = 2
            can_join = can_continue = True
            end += 1
        if joined and can_join:
            total -= 2
        total += w
        joined = False
        last_emoji = can_continue
        i = end
    # The measuring pass recognizes cursive ligatures even across grapheme
    # boundaries. Rendering calls this function on one grapheme at a time.
    for i, cp in enumerate(cps):
        if cp in LAM:
            j = i + 1
            while j < len(cps) and cps[j] != 0x200D and char_width(cps[j]) == 0:
                j += 1
            if j < len(cps) and cps[j] in ALEF:
                total -= 1
    # Tifinagh consonant pairs can be written using either of two joiners.
    i = 0
    while i + 2 < len(cps):
        if (0x2D31 <= cps[i] <= 0x2D65 and cps[i + 1] in (0x200D, 0x2D7F)
                and 0x2D31 <= cps[i + 2] <= 0x2D65):
            total -= 1 + char_width(cps[i + 1], measuring)
            i += 3
        else:
            i += 1
    return max(0, total)


PREPEND = (
    (0x600, 0x605), (0x6DD, 0x6DD), (0x70F, 0x70F), (0x890, 0x891), (0x8E2, 0x8E2),
    (0xD4E, 0xD4E), (0x110BD, 0x110BD), (0x110CD, 0x110CD), (0x111C2, 0x111C3),
    (0x1193F, 0x1193F), (0x11941, 0x11941), (0x11A3A, 0x11A3A), (0x11A84, 0x11A89),
    (0x11D46, 0x11D46), (0x11F02, 0x11F02),
)
CONSONANTS = (
    (0x915, 0x939), (0x958, 0x95F), (0x978, 0x97F),
    (0x995, 0x9A8), (0x9AA, 0x9B0), (0x9B2, 0x9B2), (0x9B6, 0x9B9), (0x9DC, 0x9DF),
    (0x9F0, 0x9F1), (0xA95, 0xAA8), (0xAAA, 0xAB0), (0xAB2, 0xAB3), (0xAB5, 0xAB9),
    (0xAF9, 0xAF9), (0xB15, 0xB28), (0xB2A, 0xB30), (0xB32, 0xB33), (0xB35, 0xB39),
    (0xB5C, 0xB5D), (0xB5F, 0xB5F), (0xB71, 0xB71),
    (0xC15, 0xC28), (0xC2A, 0xC39), (0xC58, 0xC5A), (0xD15, 0xD3A),
)
LINKERS = {0x94D, 0x9CD, 0xACD, 0xB4D, 0xC4D, 0xD4D}


@lru_cache(maxsize=32768)
def grapheme_property(cp):
    if cp == 13:
        return 'CR'
    if cp == 10:
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F:
        return 'Extend'
    if contains(PREPEND, cp):
        return 'Prepend'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    category = unicodedata.category(chr(cp))
    if category in ('Cc', 'Cf', 'Zl', 'Zp'):
        return 'Control'
    if category in ('Mn', 'Me'):
        return 'Extend'
    joins = contains(PICTOGRAPHIC, cp)
    if category == 'Mc':
        return 'SpacingMark' if joins or char_width(cp) == 0 else 'Other'
    if cp in (0xFF9E, 0xFF9F):
        return 'Extend'
    if category == 'Cn' and joins and not (0x1F000 <= cp <= 0x1FFFF):
        return 'Extend'
    if joins:
        return 'EP'
    return 'Other'


def graphemes(text):
    if not text:
        return
    cps = [ord(c) for c in text]
    props = [grapheme_property(n) for n in cps]
    start = 0
    ri_count = int(props[0] == 'RI')
    control = ('CR', 'LF', 'Control')
    for i in range(1, len(cps)):
        previous, current = props[i - 1], props[i]
        join = False
        if previous == 'CR' and current == 'LF':
            join = True
        elif previous in control or current in control:
            pass
        elif previous == 'L' and current in ('L', 'V', 'LV', 'LVT'):
            join = True
        elif previous in ('LV', 'V') and current in ('V', 'T'):
            join = True
        elif previous in ('LVT', 'T') and current == 'T':
            join = True
        elif current in ('Extend', 'ZWJ', 'SpacingMark') or previous == 'Prepend':
            join = True
        elif current == 'EP' and previous == 'ZWJ':
            j = i - 2
            while j >= start and props[j] == 'Extend':
                j -= 1
            join = j >= start and props[j] == 'EP'
        elif previous == current == 'RI' and ri_count % 2:
            join = True
        elif contains(CONSONANTS, cps[i]):
            j = i - 1
            linker = False
            while j >= start and props[j] in ('Extend', 'ZWJ'):
                linker = linker or cps[j] in LINKERS
                j -= 1
            join = linker and j >= start and contains(CONSONANTS, cps[j])
        if not join:
            yield text[start:i]
            start = i
            ri_count = 0
        if current == 'RI':
            ri_count += 1
        else:
            ri_count = 0
    yield text[start:]


@lru_cache(maxsize=32768)
def clipped(text, width):
    if text.isascii() and '\r\n' not in text:
        return text[:width], min(len(text), width)
    size = 0
    end = 0
    for group in graphemes(text):
        w = text_width(group)
        if size + w > width:
            break
        size += w
        end += len(group)
    return text[:end], size


def cell(text, width, padding, alignment):
    text, used = clipped(text, width)
    free = width - used
    left = 0 if alignment == 'left' else free if alignment == 'right' else free // 2
    return ' ' * (padding + left) + text + ' ' * (padding + free - left)
