"""Streaming table composition for the eight supported border styles."""
from text_layout import text_width, cell

# Top, middle and bottom rules are (left, horizontal, junction, right).
SHARP = ('┌─┬┐', '├─┼┤', '└─┴┘', '│││')
BORDERS = {
    'sharp': SHARP,
    'grid': SHARP,
    'rounded': ('╭─┬╮', '├─┼┤', '╰─┴╯', '│││'),
    'reinforced': ('┏─┬┓', '├─┼┤', '┗─┴┛', '│││'),
    'ascii': ('+-++', '+-++', '+-++', '|||'),
    'ascii2': (None, ' -+ ', None, ' | '),
    'markdown': (None, '|-||', None, '|||'),
    'none': (None, None, None, ''),
}


def render(reader, config, write):
    try:
        first = next(reader)
    except StopIteration:
        first = []
        empty = True
    else:
        empty = False
    widths = [0] * len(first)
    if config.number:
        widths.insert(0, 1)
    header = None
    buffered = []
    line_number = 0

    def numbered(row):
        nonlocal line_number
        line_number += 1
        return [str(line_number)] + row if config.number else row

    if not config.no_headers:
        header = ['#'] + first if config.number else first
    elif not empty:
        buffered.append(numbered(first))

    if not empty:
        while config.sniff == 0 or len(buffered) < config.sniff:
            try:
                row = next(reader)
            except StopIteration:
                break
            buffered.append(numbered(row))
    for row in ([header] if header is not None else []) + buffered:
        for i, value in enumerate(row):
            widths[i] = max(widths[i], text_width(value, True))

    top, middle, bottom, vertical = BORDERS[config.style]
    indentation = ' ' * config.indent

    def rule(chars):
        if chars:
            left, horizontal, cross, right = chars
            write(indentation + left + cross.join(horizontal * (w + 2 * config.padding)
                                                  for w in widths) + right + '\n')

    def draw(row, align):
        if vertical:
            left, sep, right = vertical
        else:
            left = sep = right = ''
        write(indentation + left + sep.join(cell(value, w, config.padding, align)
                                           for value, w in zip(row, widths)) + right + '\n')

    rule(top)
    if header is not None:
        draw(header, config.header_align)
    prior = header is not None
    first_body = True
    for row in buffered:
        if prior and (first_body or config.style == 'grid'):
            rule(middle)
        draw(row, config.body_align)
        first_body = False
        prior = True
    # An error in the unbuffered portion is still a next row for purposes of
    # emitting the separator, but is never rendered as a cell row.
    while not empty:
        try:
            row = next(reader)
        except StopIteration:
            break
        except Exception:
            if prior and (first_body or config.style == 'grid'):
                rule(middle)
            raise
        if prior and (first_body or config.style == 'grid'):
            rule(middle)
        draw(numbered(row), config.body_align)
        prior = True
        first_body = False
    rule(bottom)
