#!/usr/bin/env python3
"""A standalone CSV/TSV terminal viewer."""
import os
import sys

from cli import parse_args, CLIExit
from csv_reader import CSVReader, CSVError
from table import render


def main():
    try:
        config = parse_args()
    except CLIExit as e:
        (sys.stdout if e.status == 0 else sys.stderr).write(e.text)
        return e.status
    try:
        if config.file is None:
            data = sys.stdin.buffer.read()
        else:
            with open(config.file, 'rb') as f:
                data = f.read()
        out = sys.stdout.buffer
        render(CSVReader(data, config.delimiter), config, lambda s: out.write(s.encode('utf-8')))
        out.flush()
    except CSVError as e:
        sys.stderr.write('csview: ' + str(e) + '\n')
        return 1
    except BrokenPipeError:
        sys.stdout = open(os.devnull, 'w')
        return 0
    except OSError as e:
        sys.stderr.write(f'csview: {e.strerror} (os error {e.errno})\n')
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
