"""Optional ANSI styling for terminal help and command-line diagnostics."""
import os
import re
import sys

RESET = '\x1b[0m'
BOLD_GREEN = '\x1b[1m\x1b[32m'
BOLD_YELLOW = '\x1b[1m\x1b[33m'
BOLD_RED = '\x1b[1m\x1b[31m'
GREEN = '\x1b[32m'
YELLOW = '\x1b[33m'
CYAN = '\x1b[36m'


def paint(text, color):
    return color + text + RESET


def enabled(stream):
    if os.environ.get('NO_COLOR'):
        return False
    if os.environ.get('CLICOLOR_FORCE'):
        return True
    return stream.isatty() and os.environ.get('TERM') != 'dumb'


def flag_line(line):
    # Keep the space before an option value in its own style run.
    token = re.compile(r'(--[a-z-]+|-[a-zA-Z])|( <[A-Z_]+>)|(\\[[A-Z]+\\])')
    def replace(m):
        if m[1]:
            return paint(m[1], BOLD_GREEN)
        if m[2]:
            return paint(' ', CYAN) + paint(m[2][1:], CYAN)
        return paint(m[3], CYAN)
    return token.sub(replace, line)


def quote_colors(line, colors):
    index = 0
    def replace(m):
        nonlocal index
        color = colors[min(index, len(colors) - 1)]
        index += 1
        return "'" + paint(m[1], color) + "'"
    return re.sub(r"'([^']*)'", replace, line)


def format_cli(text, stream, status):
    if not enabled(stream):
        return text
    result = []
    prog = os.path.basename(sys.argv[0]) or 'executable'
    for line in text.splitlines(keepends=True):
        ending = '\n' if line.endswith('\n') else ''
        line = line[:-1] if ending else line
        if line.startswith('Usage: '):
            tail = line[len('Usage: ') + len(prog):]
            if tail.startswith(' <FILE|'):
                tail = ' ' + paint(tail[1:], CYAN)
            elif ' <FILE|' in tail:
                before, group = tail.split(' <FILE|', 1)
                tail = flag_line(before) + ' ' + paint('<FILE|' + group, CYAN)
            else:
                tail = flag_line(tail)
                tail = re.sub(r'(?<!\\x1b)\\[[A-Z]+\\]|<FILE>', lambda m: paint(m[0], CYAN), tail)
            line = paint('Usage:', BOLD_YELLOW) + ' ' + paint(prog, BOLD_GREEN) + tail
        elif status == 0:
            if line in ('Arguments:', 'Options:'):
                line = paint(line, BOLD_YELLOW)
            elif line == '  [FILE]':
                line = '  ' + paint('[FILE]', CYAN)
            elif line.lstrip().startswith('-'):
                line = flag_line(line)
        elif line.startswith('error:'):
            body = line[len('error:'):]
            colors = [YELLOW, BOLD_GREEN] if body.lstrip().startswith(('invalid value', 'unexpected value')) else [YELLOW]
            line = paint('error:', BOLD_RED) + quote_colors(body, colors)
        elif line.startswith('  [possible values: '):
            vals = line[len('  [possible values: '):-1]
            line = '  [possible values: ' + ', '.join(paint(v, GREEN) for v in vals.split(', ')) + ']'
        elif line.startswith('  tip:'):
