            colors = [YELLOW, GREEN] if body.startswith(' to pass ') else [GREEN]
            line = '  ' + paint('tip:', GREEN) + quote_colors(body, colors)
        elif line.startswith('For more information, try '):
            line = quote_colors(line, [BOLD_GREEN])
        result.append(line + ending)
    return ''.join(result)
